79	func validateImagePixelCount(imageData []byte) error {
80		config, _, err := image.DecodeConfig(bytes.NewReader(imageData))
81		if err != nil {
82			// Some formats supported by imaging do not expose dimensions through
83			// the standard image registry. Let the full decoder handle those.
84			return nil //nolint:nilerr
85		}
86		if config.Width <= 0 || config.Height <= 0 {
87			return errors.New("invalid image dimensions")
88		}
89		if config.Width > maxImagePixels/config.Height {
90			return errors.Errorf("image dimensions exceed maximum of %d pixels", maxImagePixels)
91		}
92		return nil
93	}
